import { test, expect } from '@playwright/test';

test.describe('Video Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should open the video modal', async ({ page }) => {
    await page.getByRole('button', { name: /open video modal/i }).click();
    const modal = page.getByRole('dialog', { name: /video modal/i });
    await expect(modal).toBeVisible();
  });

  test('should pause the video when the modal is closed', async ({ page }) => {
    await page.getByRole('button', { name: /open video modal/i }).click();
    const video = page.getByRole('video');
    await expect(video).toBeVisible();

    await page.getByRole('button', { name: /close/i }).click();
    await expect(video).toHaveAttribute('paused', 'true');
  });
});
